def _try_to_get_filename(obj):
    """
    Try to get file name from given path or file object.

    :param obj: a file, file-like object or something
    :return: File name or None

    >>> _try_to_get_filename("a.py")
    'a'
    """
    if hasattr(obj, "name"):
        return os.path.splitext(obj.name)[0]
    elif hasattr(obj, "read"):
        return os.path.splitext(obj.name)[0]
    else:
        return os.path.splitext(obj)[0]


def _try_to_get_path(obj):
    """
    Try to get file path from given path or file object.

    :param obj: a file, file-like object or something
    :return: File path or None

    >>> _try_to_get_path("a.py")
    'a.py'
    """
    if hasattr(obj, "name"):
        return obj.name
    elif hasattr(obj, "read"):
        return obj.name
    else:
        return obj


def _try_to_get_file_object(obj):
    """
    Try to get file object from given path or file object.

    :param obj: a file, file-like object or something
    :return: File object or None

    >>> _try_to_get_file_object("a.py")
    <_io.TextIOWrapper name='a.py' mode='r' encoding='UTF-8'>
    """
    if hasattr(obj, "read"):
        return obj
    else:
        return open(obj, "r")


